SourceCode.Declaration:
[DataContractAttribute]
class ABSMRPAssessmentContract
{
    ReqPlanId    planId;
    NoYes        includeItemChecks;
    int          deletePreviousRunsDays;
}

Method.Source:
[DataMemberAttribute('PlanId'),
 SysOperationLabelAttribute(literalStr("@ABS:MRPPlanId")),
 SysOperationDisplayOrderAttribute('1')]
public ReqPlanId parmPlanId(ReqPlanId _planId = planId)
{
    planId = _planId;
    return planId;
}

[DataMemberAttribute('IncludeItemChecks'),
 SysOperationLabelAttribute(literalStr("@ABS:IncludeItemChecks")),
 SysOperationDisplayOrderAttribute('2')]
public NoYes parmIncludeItemChecks(NoYes _includeItemChecks = includeItemChecks)
{
    includeItemChecks = _includeItemChecks;
    return includeItemChecks;
}

[DataMemberAttribute('DeletePreviousRunsDays'),
 SysOperationLabelAttribute(literalStr("@ABS:DeletePreviousRunsDays")),
 SysOperationDisplayOrderAttribute('3')]
public int parmDeletePreviousRunsDays(int _deletePreviousRunsDays = deletePreviousRunsDays)
{
    deletePreviousRunsDays = _deletePreviousRunsDays;
    return deletePreviousRunsDays;
}

public void new()
{
    super();

    includeItemChecks      = NoYes::Yes;
    deletePreviousRunsDays = 30;
}
